import sys
import os


def grade(score):
    if score > 90:
        return "A"
    elif score > 80:
        return "B"
    elif score > 70:
        if score % 2:
            return "C+"
        return "C"
    else:
        return "F"


def label(score):
    """The letter for a score, top band first."""
    return grade(score)


def total(xs):
    t = 0
    for x in xs:
        if x is not None:
            t += x
    return t

